import * as THREE from './three.module.js';
import {createFootwork} from './footwork.js';
import {refinePlayer} from './player-details.js';
import {createArmRig} from './arm-rig.js';
export function createPlayer(scene,color,wood){const mat=(color,roughness=.9)=>new THREE.MeshStandardMaterial({color,roughness});const g=new THREE.Group(),body=new THREE.Group();g.add(body);const shirt=mat(color),skin=mat(['#bc8c6b','#cea080','#a87959','#d2ab8c'][Math.floor(Math.random()*4)]),white=mat('#e4dfcb');const torso=new THREE.Mesh(new THREE.LatheGeometry([[.18,-.29],[.19,-.25],[.225,.06],[.23,.18],[.215,.24],[.15,.29],[.095,.31]].map(([r,y])=>new THREE.Vector2(r,y)),28),shirt);// An oval rib cage with small cloth folds avoids a cylindrical molded torso.
const vertices=torso.geometry.attributes.position;for(let i=0;i<vertices.count;i++){const x=vertices.getX(i),y=vertices.getY(i),z=vertices.getZ(i),a=Math.atan2(z,x),fold=1+.014*Math.sin(a*7+y*19)*Math.max(0,1-Math.abs(y)/.32);vertices.setXYZ(i,x*fold,y,z*.82*fold);}torso.geometry.computeVertexNormals();torso.position.y=1.1;body.add(torso);const collar=new THREE.Mesh(new THREE.TorusGeometry(.081,.009,10,32),white);collar.rotation.x=Math.PI/2;collar.position.y=1.4;body.add(collar);const neck=new THREE.Mesh(new THREE.CylinderGeometry(.057,.073,.14,24),skin);neck.position.y=1.44;body.add(neck);const head=new THREE.Mesh(new THREE.SphereGeometry(.135,32,24),skin);head.position.y=1.6;body.add(head);const hair=new THREE.Mesh(new THREE.SphereGeometry(.14,32,24,0,Math.PI*2,0,Math.PI*.42),mat('#493d31'));hair.position.y=1.625;body.add(hair);const nose=new THREE.Mesh(new THREE.SphereGeometry(.035,8,6),skin);nose.scale.set(.65,1,.8);nose.position.set(0,1.59,.13);body.add(nose);const left=new THREE.Mesh(new THREE.CylinderGeometry(.065,.047,.57,12),skin);left.position.set(.3,1.04,.05);left.rotation.z=.18;body.add(left);const hips=new THREE.Mesh(new THREE.LatheGeometry([[.17,-.14],[.21,-.11],[.22,.01],[.20,.13],[.18,.15]].map(([r,y])=>new THREE.Vector2(r,y)),32),white);hips.scale.set(1,.65,.7);hips.position.y=.81;g.add(hips);const footRig=createFootwork(skin,white);g.add(footRig.root);const bands={head:true,wrist:true,material:mat('#f2eee1'),wristMaterial:mat('#f2eee1')};const armRig=createArmRig(skin,shirt,wood,bands.wristMaterial);body.add(armRig.root);const detailRig=refinePlayer({body,head,hair,nose,left,skin,shirt,white,hips,bands});const pickupBall=new THREE.Mesh(new THREE.SphereGeometry(.075,12,8),mat('#d6bb52'));pickupBall.position.set(.28,.87,.22);pickupBall.visible=false;body.add(pickupBall);scene.add(g);return {clothing:{shirt,base:white,shirtColor:color,baseColor:'#e4dfcb'},skin,hair,bands,energy:100,detailRig,celebrate:0,readyBlend:1,pickupBall,g,body,hips,footRig,armRig,swing:0,target:new THREE.Vector3(),velocity:{vx:0,vz:0},walk:0,hand:1,visualHand:1,plant:0,motionSpeed:0,motionVX:0,motionVZ:0,prediction:null,handCandidate:1,handCandidateSince:0};}

